def kth_element(arr, k):
    """
    :param arr: List[int]
    :param k: int
    :return: int
    """
    if k == 0:
        return arr[0]
    if k == 1:
        return arr[1]

    left, right = 0, len(arr) - k
    while left < right:
        mid = (left + right) // 2
        if arr[mid] < k:
            left = mid + 1
        else:
            right = mid
    return arr[left]

