def reverse_vowels(s: str) -> str:
    vowels = 'aeiouAEIOU'
    s = list(s)
    left, right = 0, len(s) - 1
    while left < right:
        while left < right and vowels.count(s[left]) == 0:
            left += 1
        while left < right and vowels.count(s[right]) == 0:
            right -= 1
        s[left], s[right] = s[right], s[left]
        left += 1
        right -= 1
    return ''.join(s)

