def find_solution(a, b, n):
    # Initialize the search range
    low = 1
    high = n

    # Perform binary search
    while low <= high:
        mid = (low + high) // 2
        if a * mid + b == n:
            return mid
        elif a * mid + b < n:
            low = mid + 1
        else:
            high = mid - 1

    # If no solution is found, return None
    return None

