def next_Perfect_Square(n):
    """
    :type n: int
    :rtype: int
    """
    left = 1
    right = n
    while left <= right:
        mid = (left + right) // 2
        if mid * mid == n:
            return mid
        elif mid * mid < n:
            left = mid + 1
        else:
            right = mid - 1
    return left - 1

