def count_Primes_nums(n):
    """
    :param n: a non-negative number
    :return: the number of prime numbers less than n
    """
    if n < 2:
        return 0

    # Initialize a list to store the number of prime numbers less than n
    prime_numbers = [True] * n

    # 0 and 1 are not prime numbers
    prime_numbers[0] = prime_numbers[1] = False

    # Iterate from 2 to sqrt(n)
    for i in range(2, int(n ** 0.5) + 1):
        # If i is a prime number, mark its multiples as non-prime
        if prime_numbers[i]:
            for j in range(i * i, n, i):
                prime_numbers[j] = False

    # Return the count of prime numbers
    return sum(prime_numbers)

