def max_sub_array_sum_repeated(arr, k, n):
    # Initialize the maximum sum and the current sum
    max_sum = 0
    current_sum = 0

    # Iterate over the array
    for i in range(n):
        # Add the current element to the current sum
        current_sum += arr[i]

        # If the current sum exceeds k, break the loop
        if current_sum > k:
            break

        # If the current sum is greater than k, reset the current sum to the previous element
        if current_sum > k:
            current_sum = arr[i]

    # Return the maximum sum found
    return max(max_sum, current_sum)

