def max_sum_increasing_subseq(arr, k, n):
    # Initialize the dp array with zeros
    dp = [0] * n

    # Iterate over the array starting from the second element
    for i in range(1, n):
        # Initialize the current element to the previous element
        j = i - k

        # If the current element is greater than the previous element, update the dp array
        if arr[j] > arr[i]:
            # Update the dp array with the maximum sum of the current element and the sum of the previous element and the previous element
            dp[i] = max(dp[i], dp[j] + arr[i])
        else:
            # If the current element is not greater than the previous element, update the dp array with the maximum sum of the current element and the sum of the previous element and the previous element
            dp[i] = max(dp[i], dp[j] + arr[i])

    # Return the maximum sum of the subsequence
    return dp[n - 1]


