def highest_Power_of_2(n):
    """
    :type n: int
    :rtype: int
    """
    if n < 0:
        return -1
    if n == 0:
        return 0
    if n == 1:
        return 1
    if n == 2:
        return 2
    if n % 2 == 0:
        return highest_Power_of_2(n - 1) + 1
    else:
        return highest_Power_of_2(n - 1)

