def last_Digit_Factorial(n):
    """
    :param n: int
    :return: int
    """
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")
    if n == 0:
        return 1
    if n == 1:
        return 0
    if n == 2:
        return 1
    factorial = [1]
    while n > 1:
        factorial.append(factorial[-1] * n)
        n -= 1
    return factorial[-1]

