def find_kth(arr1, arr2, k):
    """
    :param arr1: first sorted array
    :param arr2: second sorted array
    :param k: kth element to find
    :return: the kth element from arr1 and arr2
    """
    if not arr1:
        return arr2[k-1]
    if not arr2:
        return arr1[k-1]

    if k == 1:
        return min(arr1[0], arr2[0])

    if k == 2:
        return min(arr1[0], arr2[1])

    mid = (len(arr1) + len(arr2)) // 2

    if arr1[mid-1] < arr2[mid-1]:
        return find_kth(arr1[mid-1:], arr2, k-mid)
    else:
        return find_kth(arr1, arr2, k-mid)

