def get_median(nums1, nums2, k):
    """
    :param nums1: List[int]
    :param nums2: List[int]
    :param k: int
    :return: float
    """
    if len(nums1) == 0:
        return nums2[k-1]
    if len(nums2) == 0:
        return nums1[k-1]
    if k == 1:
        return min(nums1[0], nums2[0])
    if k == 2:
        return (min(nums1[0], nums2[1]) + max(nums1[1], nums2[1])) / 2

    m = k//2
    left = nums1[:m]
    right = nums1[m:]

    if len(left) == 0:
        return right[k-1]
    if len(right) == 0:
        return left[k-1]

    if len(left) == 1:
        return min(left[0], right[0])
    if len(right) == 1:
        return min(left[0], right[0])

    if left[0] < right[0]:
        return get_median(left[1:], right, k)
    else:
        return get_median(left, right, k-k//2)

