def power_base_sum(base, power):
    """
    :param base: int
    :param power: int
    :return: int
    """
    # Base case: if power is 0, return 1
    if power == 0:
        return 1
    # Base case: if power is 1, return the base itself
    if power == 1:
        return base
    # Base case: if power is even, return the base raised to half the power
    if power % 2 == 0:
        return power_base_sum(base * base, power // 2)
    # Base case: if power is odd, return the base times the square of half the power
    else:
        return base * power_base_sum(base * base, power // 2)


