def find_first_occurrence(arr, target):
    """
    :param arr: List[int]
    :param target: int
    :return: int
    """
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return left if arr[left] == target else -1

