def check_expression(expression):
    stack = []
    for i in expression:
        if i == '(':
            stack.append(i)
        elif i == ')':
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def main():
    assert check_expression("{()}[{}]") == True
    assert check_expression("({[]})") == True
    assert check_expression("({[})") == False
    assert check_expression("({[})") == False

def remove_length(s, k):
    """
    :type s: str
    :type k: int
    :rtype: str
    """
    if len(s) == 0:
        return ''
    if k == 0:
        return s

    words = s.split()

    for word in words:
        if len(word) == k:
            words.remove(word)

    return ' '.join(words)

def occurance_substring(s, sub):
    """
    :param s: str
    :param sub: str
    :return: str, int, int
    """
    if len(s) == 0:
        return None, None, None

    start = 0
    while start < len(s):
        if s[start:start+len(sub)] == sub:
            return s[start:start+len(sub)], start, start+len(sub)
        start += 1
    return None, None, None

