    :param arr: List[int]
    :return: List[List[int]]
    """
    if not arr:
        return []

    result = []

    for i in range(len(arr)):
        if i == 0 or arr[i] != arr[i-1]:
            result.append(arr[i])

    return result

def find_combinations(arr):
