def is_perfect_square(n):
    """
    :param n: int
    :return: bool
    """
    if n < 0:
        return False
    if n == 0:
        return True
    if n == 1:
        return True
    left = 1
    right = n
    while left <= right:
        mid = (left + right) // 2
        if mid * mid == n:
            return True
        elif mid * mid < n:
            left = mid + 1
        else:
            right = mid - 1
    return False

